"""Bundled demo datasets (generated by scripts/generate_samples.py)."""

from __future__ import annotations

from pathlib import Path

import pandas as pd

from .io import load_path
from .utils import DataLensError

SAMPLES_DIR = Path(__file__).resolve().parent.parent / "data" / "samples"

SAMPLES = {
    "customer_churn": {
        "title": "Customer churn",
        "file": "customer_churn.csv",
        "description": "Subscription customers with usage, billing and support history. Predict who churns.",
        "target": "churned",
        "task": "classification",
    },
    "house_prices": {
        "title": "House prices",
        "file": "house_prices.csv",
        "description": "Residential listings with size, age and location. Estimate the sale price.",
        "target": "price",
        "task": "regression",
    },
    "retail_orders": {
        "title": "Retail orders",
        "file": "retail_orders.csv",
        "description": "Online orders across regions and categories. Explore sales and predict returns.",
        "target": "returned",
        "task": "classification",
    },
}


def list_samples() -> list[dict]:
    out = []
    for key, meta in SAMPLES.items():
        path = SAMPLES_DIR / meta["file"]
        if path.exists():
            out.append({"key": key, **{k: v for k, v in meta.items() if k != "file"}})
    return out


def load_sample(key: str) -> tuple[str, pd.DataFrame]:
    meta = SAMPLES.get(key)
    if meta is None:
        raise DataLensError(f"Unknown sample dataset '{key}'.", status_code=404)
    path = SAMPLES_DIR / meta["file"]
    if not path.exists():
        raise DataLensError(
            f"Sample file {meta['file']} is missing. Run `python scripts/generate_samples.py`.", status_code=404
        )
    return meta["file"], load_path(path)
